cd /workspace/project && timeout 200 python3 - <<'PY'
import json,urllib.request,subprocess
OB=subprocess.check_output("grep -oE 'sk-obs1_[A-Za-z0-9_-]+' ob_ready.txt | head -1",shell=True,text=True).strip()
def credits():
    r=urllib.request.Request("https://obscurify.ai/v1/credits",headers={"Authorization":f"Bearer {OB}"})
    try:
        with urllib.request.urlopen(r,timeout=40) as x: return x.read().decode()[:300]
    except urllib.error.HTTPError as e: return f"HTTP{e.code} {e.read().decode()[:150]}"
print("credits endpoint:",credits())
for path in ["/v1/me","/v1/usage","/v1/account","/v1/key","/v1/auth/key"]:
    r=urllib.request.Request("https://obscurify.ai"+path,headers={"Authorization":f"Bearer {OB}"})
    try:
        with urllib.request.urlopen(r,timeout=25) as x: print(path,"->",x.read().decode()[:200])
    except urllib.error.HTTPError as e: print(path,"->",e.code)
    except Exception as e: print(path,"-> err")
PY

